type AskRequest struct {
	Loop    string
	Prompt  string
	Context string
	Schema  string
}

type Asker interface {
	Ask(req AskRequest) (string, error)
}

// Embedder is the CPython embed worker. Embeds are not model calls: they
// never reach silclm and never count against a loop's model-call budget.
type Embedder interface {
	Embed(texts []string) ([][]float64, error)
	Nearest(table, needle string, limit int) ([]map[string]any, error)
	// NearestVector ranks a table's rows by cosine similarity to vector
	// (sqlite-vec), best first, at most limit rows.
	NearestVector(table string, vector []float64, limit int) ([]map[string]any, error)
}

type Page struct {
	URL    string `json:"url"`
	Status int    `json:"status"`
	Title  string `json:"title"`
	Text   string `json:"text"`
	// HTML is the raw body for :select and :into; it is never recorded.
	HTML string `json:"-"`
}

type Kernel struct {
	db       *sql.DB
	plan     *Plan
	plansDir string
	plans    map[string]*Plan
	now      func() time.Time
	asker    Asker
	embedder Embedder
	fetch    func(url string) (Page, error)
	// render loads a page in the Playwright worker (scrape::render).
	render func(url string) (Page, error)
	mcp      func(server, tool string, args map[string]any, token string) (map[string]any, error)
	// crash is a test hook called at effect checkpoints ("after_reserve").
	crash func(point, path string)
	logf  func(format string, args ...any)
	// progress, when set, narrates each step of a run (command mode).
	progress func(format string, args ...any)
}

func (c *runCtx) progress(format string, args ...any) {
	if c.k.progress != nil {
		c.k.progress(c.lp.Name+": "+format, args...)
	}
}

func NewKernel(db *sql.DB, plan *Plan, plansDir string) (*Kernel, error) {
	k := &Kernel{
		db:       db,
		plan:     plan,
		plansDir: plansDir,
		plans:    map[string]*Plan{plan.Hash: plan},
		now:      time.Now,
		fetch:    fetchPage,
		render:   renderPage,
		mcp:      mcpCall,
		logf: func(format string, args ...any) {
			fmt.Fprintf(os.Stderr, "silc loop: "+format+"\n", args...)
		},
	}
	if plansDir != "" {
		if err := os.MkdirAll(plansDir, 0o755); err == nil {
			pinned := filepath.Join(plansDir, plan.Hash+".json")
			if _, err := os.Stat(pinned); errors.Is(err, os.ErrNotExist) {
				if data, err := json.MarshalIndent(plan, "", "  "); err == nil {
					_ = os.WriteFile(pinned, data, 0o644)
				}
			}
		}
	}
	return k, k.initSchema()
}

func (k *Kernel) initSchema() error {
	tables := append([]string{}, k.plan.ResourceTables...)
	for _, t := range []string{k.plan.Tables.Runs, k.plan.Tables.Approvals, k.plan.Tables.Notices, k.plan.Tables.Requests} {
		if t != "" && !contains(tables, t) {
			tables = append(tables, t)
		}
	}
	for _, t := range tables {
		if _, err := k.db.Exec(fmt.Sprintf(`CREATE TABLE IF NOT EXISTS %s (
			id TEXT PRIMARY KEY,
			data TEXT NOT NULL,
			created_at TEXT NOT NULL DEFAULT (datetime('now')),
			updated_at TEXT NOT NULL DEFAULT (datetime('now'))
		)`, t)); err != nil {
			return err
		}
	}
	_, err := k.db.Exec(`
		CREATE TABLE IF NOT EXISTS loop_events (
			run_id TEXT NOT NULL,
			seq INTEGER NOT NULL,
			path TEXT NOT NULL,
			kind TEXT NOT NULL,
			value TEXT NOT NULL,
			at TEXT NOT NULL,
			PRIMARY KEY (run_id, seq)
		);
		CREATE INDEX IF NOT EXISTS loop_events_lookup ON loop_events (run_id, path, kind);
		CREATE TABLE IF NOT EXISTS loop_receipts (
			op TEXT NOT NULL,
			key TEXT NOT NULL,
			status TEXT NOT NULL,
			run_id TEXT NOT NULL,
			receipt TEXT NOT NULL DEFAULT '',
			at TEXT NOT NULL,
			PRIMARY KEY (op, key)
		);
		CREATE TABLE IF NOT EXISTS loop_schedule (
			loop TEXT PRIMARY KEY,
			last_seen TEXT NOT NULL
		);
		CREATE TABLE IF NOT EXISTS loop_watermarks (
			loop TEXT PRIMARY KEY,
			mark TEXT NOT NULL
		);
	`)
	return err
}

func (k *Kernel) planByHash(hash string) (*Plan, error) {
	if p, ok := k.plans[hash]; ok {
		return p, nil
	}
	p, err := loadPlan(filepath.Join(k.plansDir, hash+".json"))
	if err != nil {
		return nil, fmt.Errorf("pinned plan %s is missing: %w", hash, err)
	}
	k.plans[hash] = p
	return p, nil
}

// Tick runs one scheduler pass: triggers, then resumable runs.
func (k *Kernel) Tick() {
	for i := range k.plan.Loops {
		lp := &k.plan.Loops[i]
		var err error
		switch lp.Trigger.Kind {
		case "schedule":
			err = k.checkSchedule(lp)
		case "on_mutation":
			err = k.checkMutations(lp)
		}
		if err != nil {
			k.logf("%s: trigger: %v", lp.Name, err)
		}
	}
	if err := k.checkRequests(); err != nil {
		k.logf("manual requests: %v", err)
	}
	if err := k.resumeRuns(); err != nil {
		k.logf("resume: %v", err)
	}
}

// ---------------------------------------------------------------- rows

func (k *Kernel) dbNow() string {
	var s string
	_ = k.db.QueryRow(`SELECT datetime('now')`).Scan(&s)
	return s
}

func getRow(q interface {
	QueryRow(string, ...any) *sql.Row
}, table, id string) (map[string]any, bool, error) {
	var data string
	err := q.QueryRow(fmt.Sprintf(`SELECT data FROM %s WHERE id = ?`, table), id).Scan(&data)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, false, nil
	}
	if err != nil {
		return nil, false, err
	}
	row := map[string]any{}
	if err := json.Unmarshal([]byte(data), &row); err != nil {
		return nil, false, err
	}
	row["id"] = id
	return row, true, nil
}

func encodeData(row map[string]any) string {
	stored := map[string]any{}
	for k, v := range row {
		if k != "id" {
			stored[k] = v
		}
	}
	b, _ := json.Marshal(stored)
	return string(b)
}

func (k *Kernel) updateData(table, id string, patch map[string]any) error {
	row, ok, err := getRow(k.db, table, id)
	if err != nil || !ok {
		return err
	}
	for f, v := range patch {
		row[f] = v
	}
	_, err = k.db.Exec(fmt.Sprintf(`UPDATE %s SET data = ?, updated_at = datetime('now') WHERE id = ?`, table), encodeData(row), id)
	return err
}

func shortHash(parts ...string) string {
	h := sha256.Sum256([]byte(strings.Join(parts, "\x1f")))
	return hex.EncodeToString(h[:])[:16]
}

// ---------------------------------------------------------------- runs

type Run struct {
	ID   string
	Data map[string]any
}

func (k *Kernel) activeRun(loop string) (bool, error) {
	var n int
	err := k.db.QueryRow(fmt.Sprintf(
		`SELECT COUNT(*) FROM %s WHERE json_extract(data, '$.loop') = ? AND json_extract(data, '$.status') IN ('running', 'waiting')`,
		k.plan.Tables.Runs), loop).Scan(&n)
	return n > 0, err
}

// startRun creates at most one run per (loop, identity) and executes it.
func (k *Kernel) startRun(lp *LoopPlan, trigger, identity string, event map[string]any) (string, bool, error) {
	id := "run-" + shortHash(lp.Name, identity)
	data := map[string]any{
		"loop":        lp.Name,
		"plan":        k.plan.Hash,
		"trigger":     trigger,
		"identity":    identity,
		"status":      "running",
		"outcome":     "",
		"detail":      "",
		"started_at":  k.now().UTC().Format(time.RFC3339),
		"finished_at": "",
		"event":       event,
	}
	res, err := k.db.Exec(fmt.Sprintf(`INSERT OR IGNORE INTO %s (id, data) VALUES (?, ?)`, k.plan.Tables.Runs), id, encodeData(data))
	if err != nil {
		return id, false, err
	}
	if n, _ := res.RowsAffected(); n == 0 {
		return id, false, nil
	}
	k.logf("%s: run %s started (%s)", lp.Name, id, identity)
	k.execute(&Run{ID: id, Data: data})
	return id, true, nil
}

func (k *Kernel) loadRun(id string) (*Run, error) {
	row, ok, err := getRow(k.db, k.plan.Tables.Runs, id)
	if err != nil {
		return nil, err
	}
	if !ok {
		return nil, fmt.Errorf("run %s not found", id)
	}
	delete(row, "id")
	return &Run{ID: id, Data: row}, nil
}

// resumeRuns replays runs left running by a crash and waiting runs whose
// approvals changed or expired.
func (k *Kernel) resumeRuns() error {
	rows, err := k.db.Query(fmt.Sprintf(
		`SELECT id, json_extract(data, '$.status') FROM %s WHERE json_extract(data, '$.status') IN ('running', 'waiting') ORDER BY created_at`,
		k.plan.Tables.Runs))
	if err != nil {
		return err
	}
	type cand struct{ id, status string }
	var cands []cand
	for rows.Next() {
		var c cand
		if err := rows.Scan(&c.id, &c.status); err == nil {
			cands = append(cands, c)
		}
	}
	rows.Close()
	now := k.now().UTC().Format(time.RFC3339)
	for _, c := range cands {
		if c.status == "waiting" {
			var n int
			err := k.db.QueryRow(fmt.Sprintf(`SELECT COUNT(*) FROM %s WHERE json_extract(data, '$.run_id') = ? AND (
				(json_extract(data, '$.status') IN ('approved', 'declined') AND json_extract(data, '$.consumed') IS NULL)
				OR (json_extract(data, '$.status') = 'pending' AND json_extract(data, '$.deadline') <= ?))`,
				k.plan.Tables.Approvals), c.id, now).Scan(&n)
			if err != nil || n == 0 {
				continue
			}
		}
		run, err := k.loadRun(c.id)
		if err != nil {
			k.logf("resume %s: %v", c.id, err)
			continue
		}
		k.execute(run)
	}
	return nil
}

// RunOnce is the command mode behind `silc main.silc` for a program whose
// loops are all manual and that has no app. It finishes any run a crash left
// behind, starts every loop exactly once, writes each run's notices to `out`
// (one line per notice), and reports whether every run succeeded. The runs
// and their receipts stay in the shared SQLite file like any other run.
func (k *Kernel) RunOnce(requestedBy string, out io.Writer) (ok bool, err error) {
	if err := k.resumeRuns(); err != nil {
		return false, fmt.Errorf("resume: %w", err)
	}
	ok = true
	for i := range k.plan.Loops {
		lp := &k.plan.Loops[i]
		if lp.Trigger.Kind != "manual" {
			k.logf("%s: skipped (command mode runs manual loops only)", lp.Name)
			continue
		}
		if busy, err := k.activeRun(lp.Name); err != nil {
			return false, err
		} else if busy {
			k.logf("%s: a previous run is still waiting; nothing started", lp.Name)
			ok = false
			continue
		}
		at := k.now().UTC().Format(time.RFC3339Nano)
		event := map[string]any{"requested_by": requestedBy, "requested_at": at}
		id, started, err := k.startRun(lp, "manual", "command:"+at, event)
		if err != nil {
			return false, err
		}
		if !started {
			k.logf("%s: run %s already existed; nothing started", lp.Name, id)
			ok = false
			continue
		}
		run, err := k.loadRun(id)
		if err != nil {
			return false, err
		}
		status, _ := run.Data["status"].(string)
		outcome, _ := run.Data["outcome"].(string)
		detail, _ := run.Data["detail"].(string)
		for _, text := range k.noticesFor(id) {
			fmt.Fprintln(out, text)
		}
		switch {
		case status == "waiting":
			k.logf("%s: run %s is waiting for an approval nobody can give in command mode", lp.Name, id)
			ok = false
		case outcome == "failed":
			k.logf("%s: run %s failed: %s", lp.Name, id, detail)
			ok = false
		case outcome == "partial":
			k.logf("%s: run %s finished partially: %s", lp.Name, id, detail)
			ok = false
		case outcome == "stopped" && detail != "":
			k.logf("%s: run %s stopped: %s", lp.Name, id, detail)
		}
	}
	return ok, nil
}

// noticesFor returns the notice texts one run posted, oldest first.
func (k *Kernel) noticesFor(runID string) []string {
	if k.plan.Tables.Notices == "" {
		return nil
	}
	rows, err := k.db.Query(fmt.Sprintf(
		`SELECT json_extract(data, '$.text') FROM %s WHERE json_extract(data, '$.run_id') = ? ORDER BY created_at, rowid`,
		k.plan.Tables.Notices), runID)
	if err != nil {
		k.logf("notices for %s: %v", runID, err)
		return nil
	}
	defer rows.Close()
	var texts []string
	for rows.Next() {
		var text sql.NullString
		if rows.Scan(&text) == nil && text.Valid {
			texts = append(texts, text.String)
		}
	}
	return texts
}

// ResumeRun replays one run regardless of status (tests and operators).
func (k *Kernel) ResumeRun(id string) error {
	run, err := k.loadRun(id)
	if err != nil {
		return err
	}
	k.execute(run)
	return nil
}

type sig int

const (
	sigNone sig = iota
	sigStop
	sigFail
	sigSkip
	sigSuspend
)

type outcome struct {
	s      sig
	reason string
}

var none = outcome{}

type scope struct {
	vars   map[string]any
	parent *scope
}

func (s *scope) get(name string) (any, bool) {
	for c := s; c != nil; c = c.parent {
		if v, ok := c.vars[name]; ok {
			return v, true
		}
	}
	return nil, false
}

func (s *scope) child() *scope { return &scope{vars: map[string]any{}, parent: s} }

type runCtx struct {
	k        *Kernel
	run      *Run
	plan     *Plan
	lp       *LoopPlan
	loc      *time.Location
	recorded map[string]string
	seq      int
	partial  bool
	items    map[string]int
}

func (k *Kernel) finish(run *Run, status, outcome, detail string) {
	patch := map[string]any{"status": status, "outcome": outcome, "detail": detail}
	if status == "finished" {
		patch["finished_at"] = k.now().UTC().Format(time.RFC3339)
	}
	if err := k.updateData(k.plan.Tables.Runs, run.ID, patch); err != nil {
		k.logf("run %s: update status: %v", run.ID, err)
	}
	k.logf("run %s: %s %s %s", run.ID, status, outcome, detail)
}

func (k *Kernel) execute(run *Run) {
	loopName, _ := run.Data["loop"].(string)
	hash, _ := run.Data["plan"].(string)
	plan, err := k.planByHash(hash)
	if err != nil {
		k.finish(run, "finished", "failed", err.Error())
		return
	}
	lp := plan.loop(loopName)
	if lp == nil {
		k.finish(run, "finished", "failed", fmt.Sprintf("loop %s is not in pinned plan %s", loopName, hash))
		return
	}
	loc, err := time.LoadLocation(lp.TZ)
	if err != nil {
		k.finish(run, "finished", "failed", fmt.Sprintf("time zone %q: %v", lp.TZ, err))
		return
	}
	ctx := &runCtx{k: k, run: run, plan: plan, lp: lp, loc: loc, recorded: map[string]string{}, items: map[string]int{}}
	if err := ctx.loadEvents(); err != nil {
		k.finish(run, "finished", "failed", err.Error())
		return
	}
	if status, _ := run.Data["status"].(string); status != "running" {
		_ = k.updateData(k.plan.Tables.Runs, run.ID, map[string]any{"status": "running"})
	}
	clockNow := k.now().In(loc)
	day := func(offset int) string { return clockNow.AddDate(0, 0, offset).Format("2006-01-02") }
	clockRaw := ctx.record("clock", "clock", map[string]any{
		"now":   clockNow.Format(time.RFC3339),
		"today": day(0),
		"calendar": map[string]any{
			"today":       day(0),
			"weekday":     clockNow.Weekday().String(),
			"last7_start": day(-6),
			"last7_end":   day(0),
			"next7_end":   day(6),
		},
	})
	var clock map[string]any
	_ = json.Unmarshal([]byte(clockRaw), &clock)
	root := &scope{vars: map[string]any{
		"now":   clock["now"],
		"today": clock["today"],
		"event":    run.Data["event"],
		"calendar": clock["calendar"],
	}}
	var out outcome
	func() {
		defer func() {
			if r := recover(); r != nil {
				if _, ok := r.(crashSignal); ok {
					panic(r)
				}
				out = outcome{sigFail, fmt.Sprintf("kernel error: %v", r)}
			}
		}()
		out = ctx.block(lp.Steps, root, "", false)
	}()
	detail := ctx.itemSummary()
	switch out.s {
	case sigSuspend:
		k.finish(run, "waiting", "", joinDetail("waiting for approval", detail))
	case sigStop:
		k.finish(run, "finished", "stopped", joinDetail(out.reason, detail))
	case sigFail:
		k.finish(run, "finished", "failed", joinDetail(out.reason, detail))
	default:
		if ctx.partial {
			k.finish(run, "finished", "partial", detail)
		} else {
			k.finish(run, "finished", "succeeded", detail)
		}
	}
}

func joinDetail(a, b string) string {
	if a == "" {
		return b
	}
	if b == "" {
		return a
	}
	return a + "; " + b
}

func (c *runCtx) itemSummary() string {
	if len(c.items) == 0 {
		return ""
	}
	var parts []string
	for _, k := range []string{"done", "skipped", "failed", "waiting"} {
		if n := c.items[k]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, k))
		}
	}
	return "items: " + strings.Join(parts, ", ")
}

func (c *runCtx) loadEvents() error {
	rows, err := c.k.db.Query(`SELECT seq, path, kind, value FROM loop_events WHERE run_id = ? ORDER BY seq`, c.run.ID)
	if err != nil {
		return err
	}
	defer rows.Close()
	for rows.Next() {
		var seq int
		var path, kind, value string
		if err := rows.Scan(&seq, &path, &kind, &value); err != nil {
			return err
		}
		c.recorded[path+"|"+kind] = value
		if seq >= c.seq {
			c.seq = seq + 1
		}
	}
	return rows.Err()
}

// record returns the recorded value for (path, kind), appending it first if new.
func (c *runCtx) record(path, kind string, value any) string {
	key := path + "|" + kind
	if v, ok := c.recorded[key]; ok {
		return v
	}
	b, _ := json.Marshal(value)
	if _, err := c.k.db.Exec(`INSERT INTO loop_events (run_id, seq, path, kind, value, at) VALUES (?, ?, ?, ?, ?, ?)`,
		c.run.ID, c.seq, path, kind, string(b), c.k.now().UTC().Format(time.RFC3339Nano)); err != nil {
		panic(fmt.Sprintf("append event: %v", err))
	}
	c.seq++
	c.recorded[key] = string(b)
	return string(b)
}

func (c *runCtx) recordedValue(path, kind string) (string, bool) {
	v, ok := c.recorded[path+"|"+kind]
	return v, ok
}

func stepPath(prefix string, i int) string {
	if prefix == "" {
		return strconv.Itoa(i)
	}
	return prefix + "." + strconv.Itoa(i)
}

func (c *runCtx) block(steps []Step, sc *scope, prefix string, inEach bool) outcome {
	for i := range steps {
		out := c.step(&steps[i], sc, stepPath(prefix, i), inEach)
		if out.s != sigNone {
			return out
		}
	}
	return none
}

func (c *runCtx) step(st *Step, sc *scope, path string, inEach bool) outcome {
	switch st.Op {
	case "let":
		v, _ := eval(st.Value, sc)
		sc.vars[st.As] = v
	case "find":
		raw, ok := c.recordedValue(path, "find")
		if !ok {
			rows, err := c.find(st, sc)
			if err != nil {
				return outcome{sigFail, fmt.Sprintf("loop::find %s: %v", st.Resource, err)}
			}
			raw = c.record(path, "find", rows)
		}
		var rows []any
		_ = json.Unmarshal([]byte(raw), &rows)
		if st.One {
			if len(rows) > 0 {
				sc.vars[st.As] = rows[0]
			} else {
				sc.vars[st.As] = nil
			}
		} else {
			if rows == nil {
				rows = []any{}
			}
			sc.vars[st.As] = rows
		}
	case "read":
		raw, ok := c.recordedValue(path, "read")
		if !ok {
			switch st.ReadOp {
			case "mcp::call":
				c.progress("reading %s (%s %s)", st.As, st.ReadOp, st.Tool)
			case "", "scrape::page":
				c.progress("reading %s", st.As)
			default:
				c.progress("reading %s (%s)", st.As, st.ReadOp)
			}
			raw = c.record(path, "read", c.read(st, sc))
		}
		var res map[string]any
		_ = json.Unmarshal([]byte(raw), &res)
		if errText, _ := res["error"].(string); errText != "" {
			c.progress("read %s failed: %s", st.As, errText)
			return outcome{sigFail, "loop::read: " + errText}
		}
		c.progress("read %s ok", st.As)
		sc.vars[st.As] = res["page"]
	case "fallback":
		for i := range st.Attempts {
			attempt := &st.Attempts[i]
			attemptPath := fmt.Sprintf("%s.try%d", path, i)
			raw, ok := c.recordedValue(attemptPath, "read")
			if !ok {
				if attempt.ReadOp == "mcp::call" {
					c.progress("reading %s, attempt %d (%s %s)", st.As, i+1, attempt.ReadOp, attempt.Tool)
				} else {
					c.progress("reading %s, attempt %d", st.As, i+1)
				}
				raw = c.record(attemptPath, "read", c.read(attempt, sc))
			}
			var res map[string]any
			_ = json.Unmarshal([]byte(raw), &res)
			if errText, _ := res["error"].(string); errText != "" {
				c.progress("read %s attempt %d failed: %s", st.As, i+1, errText)
				c.record(attemptPath, "trace:fallback_rejected", "read failed: "+errText)
				continue
			}
			candidate := sc.child()
			candidate.vars[st.As] = res["page"]
			v, known := eval(st.Accept, candidate)
			if b, isBool := v.(bool); known && isBool && b {
				c.progress("read %s ok (attempt %d accepted)", st.As, i+1)
				c.record(path, "trace:fallback_accepted", i)
				sc.vars[st.As] = res["page"]
				return none
			}
			c.progress("read %s attempt %d not accepted", st.As, i+1)
			c.record(attemptPath, "trace:fallback_rejected", "not accepted")
		}
		c.progress("fallback %s: no attempt accepted", st.As)
		c.record(path, "trace:fallback_exhausted", len(st.Attempts))
		return c.block(st.Otherwise, sc.child(), path+".otherwise", inEach)
	case "ask":
		raw, ok := c.recordedValue(path, "ask")
		if !ok {
			c.progress("asking the model for %s (%s)", st.Into, st.As)
			raw = c.record(path, "ask", c.ask(st, sc))
		}
		var res map[string]any
		_ = json.Unmarshal([]byte(raw), &res)
		if okv, _ := res["ok"].(bool); !okv {
			errText, _ := res["error"].(string)
			c.progress("ask %s failed: %s", st.As, errText)
			c.record(path, "trace:ask_failed", errText)
			if st.Otherwise != nil {
				return c.block(st.Otherwise, sc.child(), path+".otherwise", inEach)
			}
			return outcome{sigFail, fmt.Sprintf("loop::ask could not produce a valid %s: %s", st.Into, errText)}
		}
		c.progress("ask %s ok", st.As)
		sc.vars[st.As] = res["value"]
	case "gate":
		v, known := eval(st.That, sc)
		if b, isBool := v.(bool); known && isBool && b {
			c.progress("gate passed")
			return none
		}
		c.progress("gate blocked: %s", st.Reason)
		c.record(path, "trace:gate_blocked", st.Reason)
		if st.Otherwise != nil {
			return c.block(st.Otherwise, sc.child(), path+".otherwise", inEach)
		}
		return outcome{sigFail, "gate blocked: " + st.Reason}
	case "branch":
		for i, arm := range st.Arms {
			v, known := eval(arm.That, sc)
			if b, isBool := v.(bool); known && isBool && b {
				return c.block(arm.Steps, sc.child(), fmt.Sprintf("%s.when%d", path, i), inEach)
			}
		}
		return c.block(st.Otherwise, sc.child(), path+".otherwise", inEach)
	case "each":
		v, known := eval(st.In, sc)
		if !known {
			return outcome{sigFail, "loop::each :in is unknown"}
		}
		list, isList := v.([]any)
		if !isList {
			return outcome{sigFail, "loop::each :in is not a list"}
		}
		if len(list) > st.Max {
			return outcome{sigFail, fmt.Sprintf("loop::each has %d items; :max is %d", len(list), st.Max)}
		}
		waiting := 0
		for i, item := range list {
			itemScope := sc.child()
			itemScope.vars[st.As] = item
			out := c.block(st.Steps, itemScope, fmt.Sprintf("%s[%d]", path, i), true)
			switch out.s {
			case sigNone:
				c.items["done"]++
			case sigSkip:
				c.items["skipped"]++
				c.record(fmt.Sprintf("%s[%d]", path, i), "trace:skipped", out.reason)
			case sigFail:
				c.items["failed"]++
				c.partial = true
				c.record(fmt.Sprintf("%s[%d]", path, i), "trace:failed", out.reason)
			case sigSuspend:
				c.items["waiting"]++
				waiting++
			case sigStop:
				return out
			}
		}
		if waiting > 0 {
			return outcome{s: sigSuspend}
		}
	case "score":
		// Not recorded: the score is a pure function of text already recorded.
		v, known := eval(st.From, sc)
		text, isStr := v.(string)
		if !known || !isStr {
			sc.vars[st.As] = nil
			c.progress("score %s unknown: its text is unknown", st.As)
			return none
		}
		sc.vars[st.As] = scoreText(text)
	case "embed":
		// loop::let + tensor::infer. Not recorded: a replay recomputes the
		// vector from the same (recorded) text. Never a model call.
		v, _ := eval(st.From, sc)
		text, isStr := v.(string)
		if !isStr {
			return outcome{sigFail, "embed :from is not a string"}
		}
		c.progress("embedding %s (%s)", st.As, st.Model)
		vec, err := c.k.embed(text)
		if err != nil {
			return outcome{sigFail, "embed: " + err.Error()}
		}
		list := make([]any, len(vec))
		for i, f := range vec {
			list[i] = f
		}
		sc.vars[st.As] = list
	case "nearest":
		raw, ok := c.recordedValue(path, "nearest")
		if !ok {
			rows, err := c.nearest(st, sc)
			if err != nil {
				return outcome{sigFail, fmt.Sprintf("nearest %s: %v", st.Resource, err)}
			}
			raw = c.record(path, "nearest", rows)
		}
		var rows []any
		_ = json.Unmarshal([]byte(raw), &rows)
		if rows == nil {
			rows = []any{}
		}
		sc.vars[st.As] = rows
	case "write":
		out := c.write(st, sc, path)
		if out.s == sigNone {
			c.progress("wrote one %s row", st.Table)
		}
		return out
	case "notify":
		out := c.notify(st, sc, path)
		if out.s == sigNone {
			c.progress("notice posted to %s", renderLoose(st.To, sc))
		}
		return out
	case "approve":
		out := c.approve(st, sc, path, inEach)
		if out.s == sigSuspend {
			c.progress("waiting for approval by %s", renderLoose(st.By, sc))
		}
		return out
	case "stop":
		return outcome{sigStop, renderLoose(st.Reason, sc)}
	case "fail":
		return outcome{sigFail, renderLoose(st.Reason, sc)}
	case "skip":
		return outcome{sigSkip, renderLoose(st.Reason, sc)}
	default:
		return outcome{sigFail, "unknown loop step " + st.Op}
	}
	return none
}

// rowMatches evaluates a find's :where against one row. Unknown is no match.
func rowMatches(st *Step, sc *scope, row map[string]any) bool {
	if st.Where == nil {
		return true
	}
	rowScope := sc.child()
	for _, f := range st.RowFields {
		if v, ok := row[f]; ok {
			rowScope.vars[f] = v
		} else {
			rowScope.vars[f] = nil
		}
	}
	v, known := eval(st.Where, rowScope)
	b, isBool := v.(bool)
	return known && isBool && b
}

func (c *runCtx) find(st *Step, sc *scope) ([]any, error) {
	if st.Nearest != nil {
		return c.findNearest(st, sc)
	}
	rows, err := c.k.db.Query(fmt.Sprintf(`SELECT id, data FROM %s ORDER BY created_at, id`, st.Table))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []any
	for rows.Next() {
		var id, data string
		if err := rows.Scan(&id, &data); err != nil {
			return nil, err
		}
		row := map[string]any{}
		if json.Unmarshal([]byte(data), &row) != nil {
			continue
		}
		row["id"] = id
		c.k.stripVector(st.Table, row)
		if !rowMatches(st, sc, row) {
			continue
		}
		out = append(out, row)
	}
	if st.Order != "" {
		sort.SliceStable(out, func(i, j int) bool {
			a := out[i].(map[string]any)[st.Order]
			b := out[j].(map[string]any)[st.Order]
			less, known := compare(a, b)
			if !known {
				return false
			}
			if st.Desc {
				return less > 0
			}
			return less < 0
		})
	}
	limit := st.Max
	if st.One {
		limit = 1
	}
	if limit > 0 && len(out) > limit {
		out = out[:limit]
	}
	if out == nil {
		out = []any{}
	}
	return out, nil
}

// vectorField is the stored vector column of a feed or `query nearest` table.
func (k *Kernel) vectorField(table string) string {
	if k.plan.Embedding == nil {
		return ""
	}
	if f, ok := k.plan.Embedding.Feeds[table]; ok {
		return f.Output
	}
	return k.plan.Embedding.Nearest[table]
}

// stripVector keeps vectors out of loop_events and loop scopes.
func (k *Kernel) stripVector(table string, row map[string]any) {
	if field := k.vectorField(table); field != "" {
		delete(row, field)
	}
}

func (k *Kernel) embed(text string) ([]float64, error) {
	if k.embedder == nil {
		return nil, fmt.Errorf("the embed worker is not running")
	}
	vecs, err := k.embedder.Embed([]string{text})
	if err != nil {
		return nil, err
	}
	if len(vecs) != 1 {
		return nil, fmt.Errorf("embed worker returned %d vectors", len(vecs))
	}
	if d := k.plan.Embedding; d != nil && d.Dimension > 0 && len(vecs[0]) != d.Dimension {
		return nil, fmt.Errorf("embed worker returned %d floats, expected %d", len(vecs[0]), d.Dimension)
	}
	return vecs[0], nil
}

// embedRow sets the feed's vector on a row about to be written. Failure is
// logged, not fatal: the row is stored without a vector and the app worker's
// sweep fills it in.
func (k *Kernel) embedRow(table string, row map[string]any) {
	if k.plan.Embedding == nil {
		return
	}
	feed, ok := k.plan.Embedding.Feeds[table]
	if !ok {
		return
	}
	delete(row, feed.Output)
	text, isStr := row[feed.Input].(string)
	if !isStr {
		return
	}
	vec, err := k.embed(text)
	if err != nil {
		k.logf("embed %s.%s failed: %v", table, feed.Input, err)
		return
	}
	row[feed.Output] = vec
}

func (c *runCtx) nearest(st *Step, sc *scope) ([]any, error) {
	if c.k.embedder == nil {
		return nil, fmt.Errorf("the embed worker is not running")
	}
	v, _ := eval(st.From, sc)
	needle, isStr := v.(string)
	if !isStr {
		return nil, fmt.Errorf(":from is not a string")
	}
	out := []any{}
	if strings.TrimSpace(needle) == "" {
		return out, nil
	}
	rows, err := c.k.embedder.Nearest(st.Table, needle, st.Max)
	if err != nil {
		return nil, err
	}
	for _, row := range rows {
		c.k.stripVector(st.Table, row)
		out = append(out, row)
	}
	return out, nil
}

// findNearest asks the embed worker for at most :max rows ranked by cosine
// similarity to :to, best first, then applies :where. The caller records the
// rows, so a replay reads them back instead of ranking again.
func (c *runCtx) findNearest(st *Step, sc *scope) ([]any, error) {
	if c.k.embedder == nil {
		return nil, fmt.Errorf("the embed worker is not running")
	}
	v, known := eval(st.Nearest.To, sc)
	if !known {
		return nil, fmt.Errorf("nearest :to is unknown")
	}
	list, isList := v.([]any)
	if !isList {
		return nil, fmt.Errorf("nearest :to is not a vector")
	}
	vec := make([]float64, len(list))
	for i, x := range list {
		f, isNum := x.(float64)
		if !isNum {
			return nil, fmt.Errorf("nearest :to has a non-number at %d", i)
		}
		vec[i] = f
	}
	if d := c.k.plan.Embedding; d != nil && d.Dimension > 0 && len(vec) != d.Dimension {
		return nil, fmt.Errorf("nearest :to has %d floats, expected %d", len(vec), d.Dimension)
	}
	limit := st.Max
	if st.One {
		limit = 1
	}
	if limit < 1 {
		return nil, fmt.Errorf("nearest needs :max")
	}
	rows, err := c.k.embedder.NearestVector(st.Table, vec, limit)
	if err != nil {
		return nil, err
	}
	if len(rows) > limit {
		rows = rows[:limit]
	}
	out := []any{}
	for _, row := range rows {
		c.k.stripVector(st.Table, row)
		delete(row, "_score")
		if !rowMatches(st, sc, row) {
			continue
		}
		out = append(out, row)
	}
	return out, nil
}

func (c *runCtx) read(st *Step, sc *scope) map[string]any {
	if st.ReadOp == "mcp::call" {
		return c.callTool(st, sc)
	}
	v, known := eval(st.URL, sc)
	url, isStr := v.(string)
	if !known || !isStr || !(strings.HasPrefix(url, "http://") || strings.HasPrefix(url, "https://")) {
		return map[string]any{"error": "url is unknown or not http(s)"}
	}
	switch st.ReadOp {
	case "scrape::site":
		return c.crawl(st, url)
	case "scrape::render":
		page, err := withRetry(st.Retry, url, c.k.render)
		if err != nil {
			return map[string]any{"error": err.Error()}
		}
		return shapePage(st, c.plan.Contracts[st.Into], page)
	case "scrape::select":
		page, err := withRetry(st.Retry, url, c.k.fetch)
		if err != nil {
			return map[string]any{"error": err.Error()}
		}
		return selectMatches(st, c.plan.Contracts[st.Into], page)
	}
	page, err := withRetry(st.Retry, url, c.k.fetch)
	if err != nil {
		return map[string]any{"error": err.Error()}
	}
	return shapePage(st, c.plan.Contracts[st.Into], page)
}

// withRetry calls get up to 1+retry times with a short backoff.
func withRetry(retry int, url string, get func(string) (Page, error)) (Page, error) {
	var lastErr error
	for attempt := 0; attempt <= retry; attempt++ {
		page, err := get(url)
		if err == nil {
			return page, nil
		}
		lastErr = err
		if attempt < retry {
			time.Sleep(time.Duration(200*(attempt+1)) * time.Millisecond)
		}
	}
	return Page{}, lastErr
}

// crawl is scrape::site: breadth-first from the start page, following links
// that match LinkCSS (default a[href]) up to Depth levels (1 is the start
// page only) and never fetching more than Max pages. Links are visited in
// page order, without fragments, each URL once. The start page must load;
// a later page that fails, or misses :select, is left out. The whole list
// is one recorded read.
func (c *runCtx) crawl(st *Step, start string) map[string]any {
	linkSel := st.LinkCSS
	if linkSel == "" {
		linkSel = "a[href]"
	}
	links, err := cascadia.Compile(linkSel)
	if err != nil {
		return map[string]any{"error": fmt.Sprintf(":link_css %q: %v", linkSel, err)}
	}
	depth := st.Depth
	if depth < 1 {
		depth = 1
	}
	startURL, err := neturl.Parse(start)
	if err != nil {
		return map[string]any{"error": fmt.Sprintf("%s: %v", start, err)}
	}
	type queued struct {
		url   string
		level int
	}
	seen := map[string]bool{canonicalURL(startURL): true}
	queue := []queued{{start, 1}}
	pages := []any{}
	fetched := 0
	for len(queue) > 0 && fetched < st.Max {
		next := queue[0]
		queue = queue[1:]
		fetched++
		page, err := withRetry(st.Retry, next.url, c.k.fetch)
		if err != nil {
			if next.level == 1 {
				return map[string]any{"error": err.Error()}
			}
			continue
		}
		if shaped := shapePage(st, c.plan.Contracts[st.Into], page); shaped["error"] == nil {
			pages = append(pages, shaped["page"])
		}
		if next.level >= depth {
			continue
		}
		doc, err := xhtml.Parse(strings.NewReader(page.HTML))
		if err != nil {
			continue
		}
		base, _ := neturl.Parse(page.URL)
		for _, a := range cascadia.QueryAll(doc, links) {
			href := attr(a, "href")
			if href == "" || base == nil {
				continue
			}
			u, err := base.Parse(href)
			if err != nil || (u.Scheme != "http" && u.Scheme != "https") {
				continue
			}
			if st.SameHost && !strings.EqualFold(u.Hostname(), startURL.Hostname()) {
				continue
			}
			key := canonicalURL(u)
			if seen[key] {
				continue
			}
			seen[key] = true
			queue = append(queue, queued{key, next.level + 1})
		}
	}
	return map[string]any{"page": pages}
}

func canonicalURL(u *neturl.URL) string {
	c := *u
	c.Fragment = ""
	c.RawFragment = ""
	return c.String()
}

func attr(n *xhtml.Node, name string) string {
	for _, a := range n.Attr {
		if a.Key == name {
			return strings.TrimSpace(a.Val)
		}
	}
	return ""
}

// selectMatches is scrape::select: every element matching CSS, in page
// order, up to Max. Each match has url (the page), text, and href (its own
// href resolved against the page, or ""). With :into each match is a row:
// same-named fields take those values and :fields selectors run inside the
// match. No match is an empty list, not an error.
func selectMatches(st *Step, contract []FieldSpec, page Page) map[string]any {
	sel, err := cascadia.Compile(st.CSS)
	if err != nil {
		return map[string]any{"error": fmt.Sprintf(":css %q: %v", st.CSS, err)}
	}
	doc, err := xhtml.Parse(strings.NewReader(page.HTML))
	if err != nil {
		return map[string]any{"error": fmt.Sprintf("%s: parse html: %v", page.URL, err)}
	}
	base, _ := neturl.Parse(page.URL)
	items := []any{}
	for _, n := range cascadia.QueryAll(doc, sel) {
		if len(items) >= st.Max {
			break
		}
		href := attr(n, "href")
		if href != "" && base != nil {
			if u, err := base.Parse(href); err == nil {
				href = u.String()
			}
		}
		match := map[string]any{"url": page.URL, "text": nodeText(n), "href": href}
		if st.Into == "" {
			items = append(items, match)
			continue
		}
		row := map[string]any{}
		for _, f := range contract {
			if css, ok := st.Fields[f.Name]; ok {
				fsel, err := cascadia.Compile(css)
				if err != nil {
					return map[string]any{"error": fmt.Sprintf(":fields %s %q: %v", f.Name, css, err)}
				}
				if m := cascadia.Query(n, fsel); m != nil {
					if v := nodeText(m); v != "" {
						row[f.Name] = v
					}
				}
				continue
			}
			if v, ok := match[f.Name]; ok {
				row[f.Name] = v
			}
		}
		items = append(items, row)
	}
	return map[string]any{"page": items}
}

// scoreText is text::score: the same CPU heuristic as the CPython score
// processor, so a loop and a pipeline score one text alike.
func scoreText(text string) float64 {
	if text == "" {
		return 0
	}
	length := float64(len([]rune(text)))
	vowels := 0
	for _, r := range strings.ToLower(text) {
		switch r {
		case 'a', 'e', 'i', 'o', 'u':
			vowels++
		}
	}
	score := math.Min(1, float64(vowels+1)/math.Max(8, length/12))
	return math.RoundToEven(score*1e4) / 1e4
}

func (c *runCtx) schemaText(contract string) string {
	var parts []string
	for _, f := range c.plan.Contracts[contract] {
		parts = append(parts, fmt.Sprintf("%q (%s)", f.Name, f.Type))
	}
	return strings.Join(parts, ", ")
}

func (c *runCtx) ask(st *Step, sc *scope) map[string]any {
	if c.k.asker == nil {
		return map[string]any{"ok": false, "error": "silclm is not connected"}
	}
	context := ""
	if st.From != nil {
		context = askContext(st.From, sc)
	}
	req := AskRequest{
		Loop:    c.lp.Name,
		Prompt:  renderLoose(st.Prompt, sc),
		Context: context,
		Schema:  c.schemaText(st.Into),
	}
	var lastErr string
	for attempt := 0; attempt <= st.Retry; attempt++ {
		reply, err := c.k.asker.Ask(req)
		if err != nil {
			lastErr = err.Error()
			continue
		}
		value, verr := checkContract(c.plan.Contracts[st.Into], reply)
		if verr == nil {
			return map[string]any{"ok": true, "value": value, "attempts": attempt + 1}
		}
		lastErr = verr.Error()
	}
	return map[string]any{"ok": false, "error": lastErr}
}

// askContext renders :from for silclm. A list of two or more plain bindings
// (`:from($a, $b)` or `:from([$a, $b])`, one plan) is sent as a JSON object
// labelled by binding path, so the prompt can refer to `release` and `seen`.
// Any other value is sent as its own JSON, unchanged.
func askContext(from *Expr, sc *scope) string {
	if labels, ok := askLabels(from); ok {
		values := make([]any, len(from.Items))
		for i := range from.Items {
			values[i], _ = eval(&from.Items[i], sc)
		}
		return renderLabelled(labels, values)
	}
	v, _ := eval(from, sc)
	b, _ := json.Marshal(v)
	context := string(b)
	if list, isList := v.([]any); isList {
		for len(list) > 1 && len(context) > maxAskContext {
			list = trimOldest(list)
			b, _ = json.Marshal(list)
			context = string(b)
		}
	}
	if len(context) > maxAskContext {
		context = context[:maxAskContext]
	}
	return context
}

func askLabels(e *Expr) ([]string, bool) {
	if e.K != "list" || len(e.Items) < 2 {
		return nil, false
	}
	labels := make([]string, len(e.Items))
	seen := map[string]int{}
	for i := range e.Items {
		label, ok := bindingPath(&e.Items[i])
		if !ok {
			return nil, false
		}
		seen[label]++
		if n := seen[label]; n > 1 {
			label = fmt.Sprintf("%s#%d", label, n)
		}
		labels[i] = label
	}
	return labels, true
}

func bindingPath(e *Expr) (string, bool) {
	switch e.K {
	case "var":
		return e.Name, true
	case "member":
		base, ok := bindingPath(e.Base)
		if !ok {
			return "", false
		}
		return base + "." + e.Field, true
	}
	return "", false
}

// renderLabelled keeps source order and splits maxAskContext across the
// values by trimming the oldest rows of the largest list first, so a long
// first binding cannot push the later ones out of the slot.
func renderLabelled(labels []string, values []any) string {
	render := func() string {
		var sb strings.Builder
		sb.WriteByte('{')
		for i, label := range labels {
			if i > 0 {
				sb.WriteByte(',')
			}
			k, _ := json.Marshal(label)
			v, _ := json.Marshal(values[i])
			sb.Write(k)
			sb.WriteByte(':')
			sb.Write(v)
		}
		sb.WriteByte('}')
		return sb.String()
	}
	out := render()
	for len(out) > maxAskContext {
		largest, size := -1, 0
		for i, v := range values {
			if list, ok := v.([]any); ok && len(list) > 1 {
				b, _ := json.Marshal(list)
				if len(b) > size {
					largest, size = i, len(b)
				}
			}
		}
		if largest < 0 {
			break
		}
		values[largest] = trimOldest(values[largest].([]any))
		out = render()
	}
	if len(out) > maxAskContext {
		out = out[:maxAskContext]
	}
	return out
}

// maxAskContext keeps one ask inside a 16KiB IPC slot after JSON escaping.
const maxAskContext = 9000

// trimOldest shortens the largest nested list (tool windows are oldest first),
// or drops the first item when the list holds no lists.
func trimOldest(list []any) []any {
	largest, size := -1, 0
	for i, item := range list {
		if inner, ok := item.([]any); ok && len(inner) > 1 {
			b, _ := json.Marshal(inner)
			if len(b) > size {
				largest, size = i, len(b)
			}
		}
	}
	if largest < 0 {
		return list[1:]
	}
	out := append([]any{}, list...)
	out[largest] = out[largest].([]any)[1:]
	return out
}

// firstJSONObject returns the first brace-balanced object in a model reply.
// A greedy match would swallow a later "}" in trailing prose and then fail
// to parse ("invalid character after top-level value").
func firstJSONObject(s string) string {
	start := strings.IndexByte(s, '{')
	if start < 0 {
		return ""
	}
	depth := 0
	inStr := false
	esc := false
	for i := start; i < len(s); i++ {
		c := s[i]
		if inStr {
			if esc {
				esc = false
				continue
			}
			if c == '\\' {
				esc = true
				continue
			}
			if c == '"' {
				inStr = false
			}
			continue
		}
		switch c {
		case '"':
			inStr = true
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				return s[start : i+1]
			}
		}
	}
	return ""
}

// jsonTypeName names the JSON value kind for contract type errors.
func jsonTypeName(v any) string {
	switch v.(type) {
	case nil:
		return "null"
	case bool:
		return "bool"
	case float64:
		return "number"
	case string:
		return "string"
	case []any:
		return "array"
	case map[string]any:
		return "object"
	default:
		return fmt.Sprintf("%T", v)
	}
}

// checkContract parses a model reply and requires every contract field with the right type.
// A blank string (including whitespace-only) is a valid Str; UUID still needs non-empty text.
func checkContract(fields []FieldSpec, reply string) (map[string]any, error) {
	match := firstJSONObject(reply)
	if match == "" {
		return nil, fmt.Errorf("reply has no JSON object")
	}
	var obj map[string]any
	if err := json.Unmarshal([]byte(match), &obj); err != nil {
		return nil, fmt.Errorf("reply is not valid JSON: %v", err)
	}
	out := map[string]any{}
	for _, f := range fields {
		v, present := obj[f.Name]
		optional := strings.HasSuffix(f.Type, "?")
		ty := strings.TrimSuffix(f.Type, "?")
		if !present {
			if optional {
				out[f.Name] = nil
				continue
			}
			return nil, fmt.Errorf("field %q is missing", f.Name)
		}
		if v == nil {
			if optional {
				out[f.Name] = nil
				continue
			}
			return nil, fmt.Errorf("field %q must be %s, got null", f.Name, ty)
		}
		ok := false
		switch ty {
		case "Str":
			s, isStr := v.(string)
			ok = isStr
			if isStr {
				v = strings.TrimSpace(s)
			}
		case "UUID":
			s, isStr := v.(string)
			ok = isStr && strings.TrimSpace(s) != ""
			if isStr {
				v = strings.TrimSpace(s)
			}
		case "Int", "int32", "int64":
			n, isNum := v.(float64)
			ok = isNum && n == math.Trunc(n)
		case "num32", "num64":
			_, ok = v.(float64)
		case "Bool":
			_, ok = v.(bool)
		case "List":
			_, ok = v.([]any)
		default:
			_, isStr := v.(string)
			_, isObj := v.(map[string]any)
			ok = isStr || isObj
		}
		if !ok {
			return nil, fmt.Errorf("field %q must be %s, got %s", f.Name, ty, jsonTypeName(v))
		}
		out[f.Name] = v
	}
	return out, nil
}

type crashSignal struct{ point, path string }

func (c *runCtx) checkpoint(point, path string) {
	if c.k.crash != nil {
		c.k.crash(point, path)
	}
}

// effect reserves a receipt, runs apply inside one transaction with the
// receipt commit, and is a no-op once the receipt is committed.
func (c *runCtx) effect(op, key, path string, apply func(tx *sql.Tx) (map[string]any, error)) outcome {
	var status string
	err := c.k.db.QueryRow(`SELECT status FROM loop_receipts WHERE op = ? AND key = ?`, op, key).Scan(&status)
	if err == nil && status == "committed" {
		c.record(path, "trace:effect_skipped", map[string]any{"op": op, "key": key})
		return none
	}
	if errors.Is(err, sql.ErrNoRows) {
		if _, err := c.k.db.Exec(`INSERT OR IGNORE INTO loop_receipts (op, key, status, run_id, at) VALUES (?, ?, 'started', ?, ?)`,
			op, key, c.run.ID, c.k.now().UTC().Format(time.RFC3339)); err != nil {
			return outcome{sigFail, "reserve receipt: " + err.Error()}
		}
	} else if err != nil {
		return outcome{sigFail, "read receipt: " + err.Error()}
	}
	c.checkpoint("after_reserve", path)
	tx, err := c.k.db.Begin()
	if err != nil {
		return outcome{sigFail, err.Error()}
	}
	receipt, err := apply(tx)
	if err != nil {
		_ = tx.Rollback()
		return outcome{sigFail, err.Error()}
	}
	b, _ := json.Marshal(receipt)
	if _, err := tx.Exec(`UPDATE loop_receipts SET status = 'committed', receipt = ?, run_id = ?, at = ? WHERE op = ? AND key = ?`,
		string(b), c.run.ID, c.k.now().UTC().Format(time.RFC3339), op, key); err != nil {
		_ = tx.Rollback()
		return outcome{sigFail, err.Error()}
	}
	if err := tx.Commit(); err != nil {
		return outcome{sigFail, err.Error()}
	}
	c.record(path, "trace:effect", map[string]any{"op": op, "key": key, "receipt": receipt})
	return none
}

func (c *runCtx) write(st *Step, sc *scope, path string) outcome {
	key, ok := renderStrict(st.Key, sc)
	if !ok {
		return outcome{sigFail, "loop::write :key has an unknown placeholder"}
	}
	v, _ := eval(st.Value, sc)
	value, isMap := v.(map[string]any)
	if !isMap {
		return outcome{sigFail, "loop::write :value is unknown"}
	}
	op := "write:" + st.Table
	return c.effect(op, key, path, func(tx *sql.Tx) (map[string]any, error) {
		if st.Mode == "update" {
			id, _ := value["id"].(string)
			if id == "" {
				return nil, fmt.Errorf("update needs an id")
			}
			row, found, err := getRow(tx, st.Table, id)
			if err != nil {
				return nil, err
			}
			if !found {
				return nil, fmt.Errorf("%s row %s not found", st.Resource, id)
			}
			for f, fv := range value {
				if f != "id" && fv != nil {
					row[f] = fv
				}
			}
			c.k.embedRow(st.Table, row)
			if _, err := tx.Exec(fmt.Sprintf(`UPDATE %s SET data = ?, updated_at = datetime('now') WHERE id = ?`, st.Table), encodeData(row), id); err != nil {
				return nil, err
			}
			return map[string]any{"table": st.Table, "id": id, "mode": "update"}, nil
		}
		id, _ := value["id"].(string)
		if id == "" {
			id = "loop-" + shortHash(op, key)
		}
		row := map[string]any{}
		for f, fv := range value {
			if fv != nil {
				row[f] = fv
			}
		}
		c.k.embedRow(st.Table, row)
		if _, err := tx.Exec(fmt.Sprintf(`INSERT OR IGNORE INTO %s (id, data) VALUES (?, ?)`, st.Table), id, encodeData(row)); err != nil {
			return nil, err
		}
		return map[string]any{"table": st.Table, "id": id, "mode": "create"}, nil
	})
}

func (c *runCtx) notify(st *Step, sc *scope, path string) outcome {
	key, ok := renderStrict(st.Key, sc)
	if !ok {
		return outcome{sigFail, "loop::notify :key has an unknown placeholder"}
	}
	to := renderLoose(st.To, sc)
	text := renderLoose(st.Text, sc)
	table := c.plan.Tables.Notices
	return c.effect("notify", key, path, func(tx *sql.Tx) (map[string]any, error) {
		id := "notice-" + shortHash(c.lp.Name, key)
		row := map[string]any{"loop": c.lp.Name, "run_id": c.run.ID, "to": to, "text": text, "key": key}
		if _, err := tx.Exec(fmt.Sprintf(`INSERT OR IGNORE INTO %s (id, data) VALUES (?, ?)`, table), id, encodeData(row)); err != nil {
			return nil, err
		}
		return map[string]any{"table": table, "id": id}, nil
	})
}

func sameName(a, b string) bool {
	return strings.EqualFold(strings.TrimSpace(a), strings.TrimSpace(b))
}

func (c *runCtx) approve(st *Step, sc *scope, path string, inEach bool) outcome {
	raw, decided := c.recordedValue(path, "approve")
	if !decided {
		table := c.plan.Tables.Approvals
		id := "apr-" + shortHash(c.run.ID, path)
		by := renderLoose(st.By, sc)
		row, found, err := getRow(c.k.db, table, id)
		if err != nil {
			return outcome{sigFail, err.Error()}
		}
		now := c.k.now()
		if !found {
			reqRaw := c.record(path, "approve_requested", map[string]any{
				"deadline": now.Add(time.Duration(st.WithinMinutes) * time.Minute).UTC().Format(time.RFC3339),
			})
			var req map[string]any
			_ = json.Unmarshal([]byte(reqRaw), &req)
			deadline, _ := req["deadline"].(string)
			show := ""
			if st.Show != nil {
				v, _ := eval(st.Show, sc)
				show = display(v)
			}
			local := deadline
			if t, err := time.Parse(time.RFC3339, deadline); err == nil {
				local = t.In(c.loc).Format("Mon Jan 2 15:04 MST")
			}
			data := map[string]any{
				"loop": c.lp.Name, "run_id": c.run.ID, "step": path, "by": by,
				"message": renderLoose(st.Message, sc), "show": show,
				"summary": fmt.Sprintf("Approver: %s · decide by %s", by, local),
				"status":  "pending", "deadline": deadline,
				"decided_by": "", "decided_at": "", "note": "",
			}
			if _, err := c.k.db.Exec(fmt.Sprintf(`INSERT OR IGNORE INTO %s (id, data) VALUES (?, ?)`, table), id, encodeData(data)); err != nil {
				return outcome{sigFail, err.Error()}
			}
			return outcome{s: sigSuspend}
		}
		status, _ := row["status"].(string)
		deadline, _ := row["deadline"].(string)
		var decision map[string]any
		switch status {
		case "approved", "declined":
			decidedBy, _ := row["decided_by"].(string)
			if !sameName(decidedBy, by) {
				_ = c.k.updateData(table, id, map[string]any{
					"status": "pending", "decided_by": "",
					"note": fmt.Sprintf("Only %s can decide this; %q tried.", by, decidedBy),
				})
				return outcome{s: sigSuspend}
			}
			decision = map[string]any{"outcome": status, "by": decidedBy, "decided_at": now.UTC().Format(time.RFC3339), "note": ""}
		default:
			if deadline != "" && now.UTC().Format(time.RFC3339) >= deadline {
				decision = map[string]any{"outcome": "timed_out", "by": "", "decided_at": now.UTC().Format(time.RFC3339), "note": ""}
			} else {
				return outcome{s: sigSuspend}
			}
		}
		raw = c.record(path, "approve", decision)
		final := decision["outcome"].(string)
		_ = c.k.updateData(table, id, map[string]any{"status": final, "decided_at": decision["decided_at"], "consumed": true})
	}
	var decision map[string]any
	_ = json.Unmarshal([]byte(raw), &decision)
	if st.As != "" {
		sc.vars[st.As] = decision
	}
	switch decision["outcome"] {
	case "approved":
		return none
	case "declined":
		return c.block(st.Declined, sc.child(), path+".declined", inEach)
	default:
		return c.block(st.TimedOut, sc.child(), path+".timed_out", inEach)
	}
}

// ---------------------------------------------------------------- expressions

func eval(e *Expr, sc *scope) (any, bool) {
	if e == nil {
		return nil, false
	}
	switch e.K {
	case "str":
		return e.S, true
	case "num":
		return e.N, true
	case "bool":
		return e.B, true
	case "var":
		v, ok := sc.get(e.Name)
		return v, ok && v != nil
	case "member":
		base, known := eval(e.Base, sc)
		if !known {
			return nil, false
		}
		switch b := base.(type) {
		case map[string]any:
			v, ok := b[e.Field]
			return v, ok && v != nil
		case []any:
			if e.Field == "count" {
				return float64(len(b)), true
			}
		}
		return nil, false
	case "not":
		v, known := eval(e.E, sc)
		b, isBool := v.(bool)
		if !known || !isBool {
			return nil, false
		}
		return !b, true
	case "neg":
		v, known := eval(e.E, sc)
		n, isNum := toNumber(v)
		if !known || !isNum {
			return nil, false
		}
		return -n, true
	case "list":
		out := make([]any, 0, len(e.Items))
		for i := range e.Items {
			v, _ := eval(&e.Items[i], sc)
			out = append(out, v)
		}
		return out, true
	case "new":
		out := map[string]any{}
		for _, f := range e.Fields {
			v, _ := eval(f.Value, sc)
			out[f.Name] = v
		}
		return out, true
	case "bin":
		return evalBin(e, sc)
	}
	return nil, false
}

func evalBin(e *Expr, sc *scope) (any, bool) {
	switch e.Op {
	case "&&", "||":
		l, lk := eval(e.L, sc)
		r, rk := eval(e.R, sc)
		lb, lIsBool := l.(bool)
		rb, rIsBool := r.(bool)
		lk = lk && lIsBool
		rk = rk && rIsBool
		if e.Op == "&&" {
			if (lk && !lb) || (rk && !rb) {
				return false, true
			}
			if lk && rk {
				return true, true
			}
			return nil, false
		}
		if (lk && lb) || (rk && rb) {
			return true, true
		}
		if lk && rk {
			return false, true
		}
		return nil, false
	}
	l, lk := eval(e.L, sc)
	r, rk := eval(e.R, sc)
	if !lk || !rk {
		return nil, false
	}
	switch e.Op {
	case "==", "!=":
		cmp, known := compare(l, r)
		if !known {
			return nil, false
		}
		return (cmp == 0) == (e.Op == "=="), true
	case "<", "<=", ">", ">=":
		cmp, known := compare(l, r)
		if !known {
			return nil, false
		}
		switch e.Op {
		case "<":
			return cmp < 0, true
		case "<=":
			return cmp <= 0, true
		case ">":
			return cmp > 0, true
		default:
			return cmp >= 0, true
		}
	case "+":
		ln, lNum := l.(float64)
		rn, rNum := r.(float64)
		if lNum && rNum {
			return ln + rn, true
		}
		return stringify(l) + stringify(r), true
	case "-", "*", "/":
		ln, lNum := toNumber(l)
		rn, rNum := toNumber(r)
		if !lNum || !rNum {
			return nil, false
		}
		switch e.Op {
		case "-":
			return ln - rn, true
		case "*":
			return ln * rn, true
		default:
			if rn == 0 {
				return nil, false
			}
			return ln / rn, true
		}
	}
	return nil, false
}

func toNumber(v any) (float64, bool) {
	switch n := v.(type) {
	case float64:
		return n, true
	case string:
		f, err := strconv.ParseFloat(strings.TrimSpace(n), 64)
		return f, err == nil
	}
	return 0, false
}

// compare orders numbers numerically, then strings lexically (ISO dates sort).
func compare(a, b any) (int, bool) {
	if a == nil || b == nil {
		return 0, false
	}
	if ab, ok := a.(bool); ok {
		bb, ok := b.(bool)
		if !ok {
			return 0, false
		}
		if ab == bb {
			return 0, true
		}
		return 1, true
	}
	an, aNum := toNumber(a)
	bn, bNum := toNumber(b)
	if aNum && bNum {
		switch {
		case an < bn:
			return -1, true
		case an > bn:
			return 1, true
		}
		return 0, true
	}
	return strings.Compare(stringify(a), stringify(b)), true
}

func stringify(v any) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case float64:
		if x == math.Trunc(x) && math.Abs(x) < 1e15 {
			return strconv.FormatInt(int64(x), 10)
		}
		return strconv.FormatFloat(x, 'f', -1, 64)
	case bool:
		return strconv.FormatBool(x)
	default:
		b, _ := json.Marshal(x)
		return string(b)
	}
}

func display(v any) string {
	m, ok := v.(map[string]any)
	if !ok {
		return stringify(v)
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var lines []string
	for _, k := range keys {
		lines = append(lines, fmt.Sprintf("%s: %s", k, stringify(m[k])))
	}
	return strings.Join(lines, "\n")
}

var placeholder = regexp.MustCompile(`\{\s*\$?([A-Za-z0-9_\-]+(?:\.[A-Za-z0-9_\-]+)*)\s*\}`)

func lookupPath(path string, sc *scope) (any, bool) {
	parts := strings.Split(path, ".")
	e := &Expr{K: "var", Name: parts[0]}
	for _, p := range parts[1:] {
		e = &Expr{K: "member", Base: e, Field: p}
	}
	return eval(e, sc)
}

func renderStrict(t string, sc *scope) (string, bool) {
	ok := true
	out := placeholder.ReplaceAllStringFunc(t, func(m string) string {
		path := placeholder.FindStringSubmatch(m)[1]
		v, known := lookupPath(path, sc)
		if !known {
			ok = false
			return ""
		}
		return stringify(v)
	})
	return out, ok
}

func renderLoose(t string, sc *scope) string {
	return placeholder.ReplaceAllStringFunc(t, func(m string) string {
		path := placeholder.FindStringSubmatch(m)[1]
		v, known := lookupPath(path, sc)
		if !known {
			return "(unknown)"
		}
		return stringify(v)
	})
}

// ---------------------------------------------------------------- triggers

type cronField struct{ set map[int]bool; any bool }

type cronSpec struct{ min, hour, dom, month, dow cronField }

func parseCronField(text string, lo, hi int) (cronField, error) {
	f := cronField{set: map[int]bool{}, any: text == "*"}
	for _, part := range strings.Split(text, ",") {
		rng, step := part, 1
		if i := strings.Index(part, "/"); i >= 0 {
			rng = part[:i]
			s, err := strconv.Atoi(part[i+1:])
			if err != nil || s <= 0 {
				return f, fmt.Errorf("bad step %q", part)
			}
			step = s
		}
		a, b := lo, hi
		if rng != "*" {
			if i := strings.Index(rng, "-"); i >= 0 {
				var err1, err2 error
				a, err1 = strconv.Atoi(rng[:i])
				b, err2 = strconv.Atoi(rng[i+1:])
				if err1 != nil || err2 != nil {
					return f, fmt.Errorf("bad range %q", rng)
				}
			} else {
				n, err := strconv.Atoi(rng)
				if err != nil {
					return f, fmt.Errorf("bad value %q", rng)
				}
				a, b = n, n
				if step > 1 {
					b = hi
				}
			}
		}
		for v := a; v <= b; v += step {
			f.set[v] = true
		}
	}
	return f, nil
}

func parseCron(text string) (*cronSpec, error) {
	fields := strings.Fields(text)
	if len(fields) != 5 {
		return nil, fmt.Errorf("cron %q needs 5 fields", text)
	}
	var c cronSpec
	var err error
	if c.min, err = parseCronField(fields[0], 0, 59); err != nil {
		return nil, err
	}
	if c.hour, err = parseCronField(fields[1], 0, 23); err != nil {
		return nil, err
	}
	if c.dom, err = parseCronField(fields[2], 1, 31); err != nil {
		return nil, err
	}
	if c.month, err = parseCronField(fields[3], 1, 12); err != nil {
		return nil, err
	}
	if c.dow, err = parseCronField(fields[4], 0, 7); err != nil {
		return nil, err
	}
	if c.dow.set[7] {
		c.dow.set[0] = true
	}
	return &c, nil
}

func (c *cronSpec) matches(t time.Time) bool {
	if !c.min.set[t.Minute()] || !c.hour.set[t.Hour()] || !c.month.set[int(t.Month())] {
		return false
	}
	domOK := c.dom.set[t.Day()]
	dowOK := c.dow.set[int(t.Weekday())]
	if c.dom.any || c.dow.any {
		return domOK && dowOK
	}
	return domOK || dowOK
}

func (k *Kernel) checkSchedule(lp *LoopPlan) error {
	cron, err := parseCron(lp.Trigger.Cron)
	if err != nil {
		return err
	}
	loc, err := time.LoadLocation(lp.Trigger.TZ)
	if err != nil {
		return err
	}
	now := k.now().UTC().Truncate(time.Minute)
	var lastText string
	err = k.db.QueryRow(`SELECT last_seen FROM loop_schedule WHERE loop = ?`, lp.Name).Scan(&lastText)
	var last time.Time
	if errors.Is(err, sql.ErrNoRows) {
		last = now.Add(-time.Minute)
	} else if err != nil {
		return err
	} else if last, err = time.Parse(time.RFC3339, lastText); err != nil {
		last = now.Add(-time.Minute)
	}
	if !now.After(last) {
		return nil
	}
	if horizon := now.Add(-31 * 24 * time.Hour); last.Before(horizon) {
		last = horizon
	}
	window := time.Duration(lp.Trigger.CatchUpMinutes) * time.Minute
	earliest := last.Add(time.Minute)
	if floor := now.Add(-window); earliest.Before(floor) {
		earliest = floor
	}
	var firing time.Time
	missed := 0
	for t := now; !t.Before(last.Add(time.Minute)); t = t.Add(-time.Minute) {
		if !cron.matches(t.In(loc)) {
			continue
		}
		if t.Before(earliest) {
			missed++
			continue
		}
		if firing.IsZero() {
			firing = t
		} else {
			missed++
		}
		if missed > 1000 {
			break
		}
	}
	if _, err := k.db.Exec(`INSERT INTO loop_schedule (loop, last_seen) VALUES (?, ?)
		ON CONFLICT(loop) DO UPDATE SET last_seen = excluded.last_seen`, lp.Name, now.Format(time.RFC3339)); err != nil {
		return err
	}
	if missed > 0 {
		k.logf("%s: %d missed firing(s) outside the catch-up window were not run", lp.Name, missed)
	}
	if firing.IsZero() {
		return nil
	}
	if busy, err := k.activeRun(lp.Name); err != nil {
		return err
	} else if busy {
		k.logf("%s: skipped firing %s; previous run is still active", lp.Name, firing.In(loc).Format(time.RFC3339))
		_, _ = k.db.Exec(`INSERT INTO loop_events (run_id, seq, path, kind, value, at)
			VALUES (?, (SELECT COALESCE(MAX(seq), -1) + 1 FROM loop_events WHERE run_id = ?), 'schedule', 'skipped_overlap', ?, ?)`,
			"loop:"+lp.Name, "loop:"+lp.Name, strconv.Quote(firing.Format(time.RFC3339)), k.now().UTC().Format(time.RFC3339Nano))
		return nil
	}
	event := map[string]any{
		"scheduled_for": firing.In(loc).Format(time.RFC3339),
		"fired_at":      k.now().In(loc).Format(time.RFC3339),
		"late":          k.now().Sub(firing) > time.Minute,
	}
	_, _, err = k.startRun(lp, "schedule", "schedule:"+firing.Format(time.RFC3339), event)
	return err
}

func (k *Kernel) checkRequests() error {
	if k.plan.Tables.Requests == "" {
		return nil
	}
	rows, err := k.db.Query(fmt.Sprintf(`SELECT id, data, created_at FROM %s WHERE json_extract(data, '$.status') = 'pending' ORDER BY created_at, id`, k.plan.Tables.Requests))
	if err != nil {
		return err
	}
	type req struct {
		id, created string
		data        map[string]any
	}
	var reqs []req
	for rows.Next() {
		var r req
		var data string
		if rows.Scan(&r.id, &data, &r.created) == nil {
			r.data = map[string]any{}
			if json.Unmarshal([]byte(data), &r.data) == nil {
				reqs = append(reqs, r)
			}
		}
	}
	rows.Close()
	for _, r := range reqs {
		name, _ := r.data["loop"].(string)
		lp := k.plan.loop(name)
		if lp == nil || (lp.Trigger.Kind != "manual" && lp.Trigger.Kind != "schedule") {
			_ = k.updateData(k.plan.Tables.Requests, r.id, map[string]any{"status": "rejected"})
			continue
		}
		if busy, err := k.activeRun(name); err != nil || busy {
			continue
		}
		by, _ := r.data["requested_by"].(string)
		event := map[string]any{"requested_by": by, "requested_at": r.created}
		runID := "run-" + shortHash(lp.Name, "manual:"+r.id)
		_ = k.updateData(k.plan.Tables.Requests, r.id, map[string]any{"status": "started", "run_id": runID})
		if _, _, err := k.startRun(lp, "manual", "manual:"+r.id, event); err != nil {
			return err
		}
	}
	return nil
}

func (k *Kernel) checkMutations(lp *LoopPlan) error {
	var mark string
	err := k.db.QueryRow(`SELECT mark FROM loop_watermarks WHERE loop = ?`, lp.Name).Scan(&mark)
	if errors.Is(err, sql.ErrNoRows) {
		_, err = k.db.Exec(`INSERT INTO loop_watermarks (loop, mark) VALUES (?, ?)`, lp.Name, k.dbNow())
		return err
	} else if err != nil {
		return err
	}
	column := "updated_at"
	extra := "AND updated_at > created_at"
	if lp.Trigger.Mutation == "create" {
		column = "created_at"
		extra = ""
	}
	rows, err := k.db.Query(fmt.Sprintf(`SELECT id, data, %s FROM %s WHERE %s >= ? %s ORDER BY %s, id`, column, lp.Trigger.Table, column, extra, column), mark)
	if err != nil {
		return err
	}
	type change struct {
		id, at string
		row    map[string]any
	}
	var changes []change
	for rows.Next() {
		var c change
		var data string
		if rows.Scan(&c.id, &data, &c.at) == nil {
			c.row = map[string]any{}
			if json.Unmarshal([]byte(data), &c.row) == nil {
				c.row["id"] = c.id
				k.stripVector(lp.Trigger.Table, c.row)
				changes = append(changes, c)
			}
		}
	}
	rows.Close()
	newMark := mark
	for _, c := range changes {
		identity := lp.Trigger.Mutation + ":" + c.id
		if lp.Trigger.Mutation == "update" {
			identity += "@" + c.at
		}
		if _, _, err := k.startRun(lp, "on_mutation", identity, c.row); err != nil {
			return err
		}
		if c.at > newMark {
			newMark = c.at
		}
	}
	if newMark != mark {
		_, err = k.db.Exec(`UPDATE loop_watermarks SET mark = ? WHERE loop = ?`, newMark, lp.Name)
	}
	return err
}

// ---------------------------------------------------------------- outside world

var (
	titleRe  = regexp.MustCompile(`(?is)<title[^>]*>(.*?)</title>`)
	scriptRe = regexp.MustCompile(`(?is)<(script|style|noscript)[^>]*>.*?</(script|style|noscript)>`)
	tagRe    = regexp.MustCompile(`(?s)<[^>]+>`)
	spaceRe  = regexp.MustCompile(`\s+`)
)

func (c *runCtx) callTool(st *Step, sc *scope) map[string]any {
	args := map[string]any{}
	if st.Args != nil {
		v, known := eval(st.Args, sc)
		m, isMap := v.(map[string]any)
		if !known || !isMap {
			return map[string]any{"error": "mcp::call :args is unknown"}
		}
		for k, fv := range m {
			if fv != nil {
				args[k] = fv
			}
		}
	}
	token := ""
	if st.AuthEnv != "" {
		token = os.Getenv(st.AuthEnv)
		if token == "" {
			return map[string]any{"error": st.AuthEnv + " is not set"}
		}
	}
	var lastErr error
	for attempt := 0; attempt <= st.Retry; attempt++ {
		res, err := c.k.mcp(st.Server, st.Tool, args, token)
		if err == nil {
			if st.Select != "" {
				res["data"] = selectPath(res["data"], st.Select)
			}
			if text, _ := res["text"].(string); len(text) > 65536 {
				res["text"] = text[:65536]
			}
			return map[string]any{"page": res}
		}
		lastErr = err
		if attempt < st.Retry {
			time.Sleep(time.Duration(200*(attempt+1)) * time.Millisecond)
		}
	}
	return map[string]any{"error": fmt.Sprintf("%s %s: %v", st.Server, st.Tool, lastErr)}
}

// selectPath walks a dotted path; a list maps the rest of the path over its items.
func selectPath(v any, path string) any {
	if path == "" {
		return v
	}
	seg, rest, _ := strings.Cut(path, ".")
	switch t := v.(type) {
	case map[string]any:
		return selectPath(t[seg], rest)
	case []any:
		out := make([]any, 0, len(t))
		for _, item := range t {
			out = append(out, selectPath(item, path))
		}
		return out
	}
	return nil
}

// mcpCall runs one MCP tool over streamable HTTP: initialize, initialized, tools/call.
func mcpCall(server, tool string, args map[string]any, token string) (map[string]any, error) {
	client := &http.Client{Timeout: 90 * time.Second}
	session := ""
	post := func(msg map[string]any) (map[string]any, error) {
		body, _ := json.Marshal(msg)
		req, err := http.NewRequest(http.MethodPost, server, bytes.NewReader(body))
		if err != nil {
			return nil, err
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Accept", "application/json, text/event-stream")
		req.Header.Set("User-Agent", "silc-loop/1")
		if token != "" {
			if strings.Contains(token, " ") {
				req.Header.Set("Authorization", token)
			} else {
				req.Header.Set("Authorization", "Bearer "+token)
			}
		}
		if session != "" {
			req.Header.Set("Mcp-Session-Id", session)
		}
		resp, err := client.Do(req)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		if sid := resp.Header.Get("Mcp-Session-Id"); sid != "" {
			session = sid
		}
		data, err := io.ReadAll(io.LimitReader(resp.Body, 8<<20))
		if err != nil {
			return nil, err
		}
		if resp.StatusCode >= 400 {
			snippet := strings.TrimSpace(string(data))
			if len(snippet) > 300 {
				snippet = snippet[:300]
			}
			return nil, fmt.Errorf("HTTP %d: %s", resp.StatusCode, snippet)
		}
		id, wantsReply := msg["id"]
		if !wantsReply {
			return nil, nil
		}
		var reply map[string]any
		if strings.HasPrefix(resp.Header.Get("Content-Type"), "text/event-stream") {
			for _, event := range strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n\n") {
				var payload []string
				for _, line := range strings.Split(event, "\n") {
					if strings.HasPrefix(line, "data:") {
						payload = append(payload, strings.TrimSpace(strings.TrimPrefix(line, "data:")))
					}
				}
				var m map[string]any
				if json.Unmarshal([]byte(strings.Join(payload, "\n")), &m) == nil && fmt.Sprint(m["id"]) == fmt.Sprint(id) {
					reply = m
					break
				}
			}
		} else if err := json.Unmarshal(data, &reply); err != nil {
			return nil, fmt.Errorf("reply is not JSON: %v", err)
		}
		if reply == nil {
			return nil, fmt.Errorf("no reply to %v", msg["method"])
		}
		if e, ok := reply["error"].(map[string]any); ok {
			return nil, fmt.Errorf("%v", e["message"])
		}
		result, _ := reply["result"].(map[string]any)
		return result, nil
	}
	if _, err := post(map[string]any{
		"jsonrpc": "2.0", "id": 1, "method": "initialize",
		"params": map[string]any{
			"protocolVersion": "2025-03-26",
			"capabilities":    map[string]any{},
			"clientInfo":      map[string]any{"name": "silc-loop", "version": "1"},
		},
	}); err != nil {
		return nil, fmt.Errorf("initialize: %w", err)
	}
	if _, err := post(map[string]any{"jsonrpc": "2.0", "method": "notifications/initialized"}); err != nil {
		return nil, fmt.Errorf("initialized: %w", err)
	}
	result, err := post(map[string]any{
		"jsonrpc": "2.0", "id": 2, "method": "tools/call",
		"params": map[string]any{"name": tool, "arguments": args},
	})
	if err != nil {
		return nil, err
	}
	var texts []string
	if content, ok := result["content"].([]any); ok {
		for _, part := range content {
			if p, ok := part.(map[string]any); ok && p["type"] == "text" {
				if t, ok := p["text"].(string); ok {
					texts = append(texts, t)
				}
			}
		}
	}
	text := strings.Join(texts, "\n")
	if isErr, _ := result["isError"].(bool); isErr {
		return nil, fmt.Errorf("tool error: %s", text)
	}
	data := result["structuredContent"]
	if data == nil {
		var parsed any
		if json.Unmarshal([]byte(text), &parsed) == nil {
			data = parsed
		} else {
			data = text
		}
	}
	return map[string]any{"text": text, "data": data}, nil
}

func fetchPage(url string) (Page, error) {
	client := &http.Client{Timeout: 20 * time.Second}
	req, err := http.NewRequest(http.MethodGet, url, nil)
	if err != nil {
		return Page{}, err
	}
	req.Header.Set("User-Agent", "SilcLoop/0.1")
	resp, err := client.Do(req)
	if err != nil {
		return Page{}, err
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
	if err != nil {
		return Page{}, err
	}
	if resp.StatusCode >= 400 {
		return Page{}, fmt.Errorf("GET %s returned %d", url, resp.StatusCode)
	}
	return pageFromHTML(url, resp.StatusCode, string(body), ""), nil
}

// pageFromHTML takes the title (unless given) and the tag-free text of body.
func pageFromHTML(url string, status int, body, title string) Page {
	if title == "" {
		if m := titleRe.FindStringSubmatch(body); m != nil {
			title = strings.TrimSpace(html.UnescapeString(spaceRe.ReplaceAllString(m[1], " ")))
		}
	}
	text := scriptRe.ReplaceAllString(body, " ")
	text = tagRe.ReplaceAllString(text, " ")
	text = strings.TrimSpace(spaceRe.ReplaceAllString(html.UnescapeString(text), " "))
	if len(text) > 8000 {
		text = text[:8000]
	}
	return Page{URL: url, Status: status, Title: title, Text: text, HTML: body}
}

// renderPage is scrape::render: the compiler's Playwright worker loads the
// page in headless Chromium and prints its DOM as JSON.
func renderPage(url string) (Page, error) {
	worker := os.Getenv("SILC_SCRAPE_BROWSER_PY")
	python := envOr("SILC_SCRAPE_PYTHON_BIN", "python3")
	if worker == "" {
		return Page{}, fmt.Errorf("scrape::render has no browser worker (SILC_SCRAPE_BROWSER_PY is unset; run `silc build`)")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()
	var stderr bytes.Buffer
	cmd := exec.CommandContext(ctx, python, worker, "--url", url, "--json")
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		msg := strings.TrimSpace(stderr.String())
		if len(msg) > 400 {
			msg = msg[len(msg)-400:]
		}
		return Page{}, fmt.Errorf("render %s: %v %s", url, err, msg)
	}
	var res struct {
		URL   string `json:"url"`
		Title string `json:"title"`
		HTML  string `json:"html"`
	}
	if err := json.Unmarshal(out, &res); err != nil {
		return Page{}, fmt.Errorf("render %s: decode worker output: %v", url, err)
	}
	if len(res.HTML) > 2<<20 {
		res.HTML = res.HTML[:2<<20]
	}
	return pageFromHTML(url, 200, res.HTML, res.Title), nil
}

// shapePage applies :select and :into to a fetched page. :select narrows to
// the first element matching the CSS selector, and `text` becomes that
// element's text; a selector that matches nothing fails the read. With :into
// the read binds a contract row: fields named url, status, title, and text
// take the page's values, a field in :fields takes the text of the first
// element inside the selection that matches its selector, and any other field
// is left out, so it is unknown and later gates fail closed.
func shapePage(st *Step, contract []FieldSpec, page Page) map[string]any {
	if st.Select == "" && st.Into == "" {
		return map[string]any{"page": page}
	}
	doc, err := xhtml.Parse(strings.NewReader(page.HTML))
	if err != nil {
		return map[string]any{"error": fmt.Sprintf("%s: parse html: %v", page.URL, err)}
	}
	root := doc
	text := page.Text
	if st.Select != "" {
		sel, err := cascadia.Compile(st.Select)
		if err != nil {
			return map[string]any{"error": fmt.Sprintf(":select %q: %v", st.Select, err)}
		}
		root = cascadia.Query(doc, sel)
		if root == nil {
			return map[string]any{"error": fmt.Sprintf("%s: :select %q matched no element", page.URL, st.Select)}
		}
		text = nodeText(root)
	}
	if st.Into == "" {
		page.Text = text
		return map[string]any{"page": page}
	}
	row := map[string]any{}
	for _, f := range contract {
		if css, ok := st.Fields[f.Name]; ok {
			sel, err := cascadia.Compile(css)
			if err != nil {
				return map[string]any{"error": fmt.Sprintf(":fields %s %q: %v", f.Name, css, err)}
			}
			if n := cascadia.Query(root, sel); n != nil {
				if v := nodeText(n); v != "" {
					row[f.Name] = v
				}
			}
			continue
		}
		switch f.Name {
		case "url":
			row["url"] = page.URL
		case "status":
			row["status"] = page.Status
		case "title":
			row["title"] = page.Title
		case "text":
			row["text"] = text
		}
	}
	return map[string]any{"page": row}
}

// nodeText is the whitespace-collapsed text under n, without script and style.
func nodeText(n *xhtml.Node) string {
	var b strings.Builder
	var walk func(*xhtml.Node)
	walk = func(n *xhtml.Node) {
		if n.Type == xhtml.ElementNode {
			switch n.Data {
			case "script", "style", "noscript", "template":
				return
			}
		}
		if n.Type == xhtml.TextNode {
			b.WriteString(n.Data)
			b.WriteByte(' ')
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(n)
	text := strings.TrimSpace(spaceRe.ReplaceAllString(b.String(), " "))
	if len(text) > 8000 {
		text = text[:8000]
	}
	return text
}

type udsAsker struct {
	conn    net.Conn
	mu      sync.Mutex
	waiters map[string]chan map[string]any
	next    int
}

func encodeFrame(value any) ([]byte, error) {
	payload, err := json.Marshal(value)
	if err != nil {
		return nil, err
	}
	buf := make([]byte, 6+len(payload))
	binary.LittleEndian.PutUint32(buf[0:4], uint32(len(payload)))
	binary.LittleEndian.PutUint16(buf[4:6], protocolVersion)
	copy(buf[6:], payload)
	return buf, nil
}

func readFrame(conn net.Conn) (map[string]any, error) {
	header := make([]byte, 6)
	if _, err := io.ReadFull(conn, header); err != nil {
		return nil, err
	}
	if binary.LittleEndian.Uint16(header[4:6]) != protocolVersion {
		return nil, fmt.Errorf("unsupported protocol")
	}
	payload := make([]byte, binary.LittleEndian.Uint32(header[0:4]))
	if _, err := io.ReadFull(conn, payload); err != nil {
		return nil, err
	}
	var out map[string]any
	return out, json.Unmarshal(payload, &out)
}

func dialSupervisor(path string) (*udsAsker, error) {
	var conn net.Conn
	var err error
	for i := 0; i < 50; i++ {
		if conn, err = net.Dial("unix", path); err == nil {
			break
		}
		time.Sleep(100 * time.Millisecond)
	}
	if conn == nil {
		return nil, err
	}
	a := &udsAsker{conn: conn, waiters: map[string]chan map[string]any{}}
	id := fmt.Sprintf("loop-%d", os.Getpid())
	if err := a.send(map[string]any{"type": "HELLO", "worker_id": id, "role": "loop", "abi_version": 1, "pid": os.Getpid()}); err != nil {
		return nil, err
	}
	if err := a.send(map[string]any{"type": "READY", "worker_id": id}); err != nil {
		return nil, err
	}
	go a.readLoop()
	return a, nil
}

func (a *udsAsker) send(v map[string]any) error {
	b, err := encodeFrame(v)
	if err != nil {
		return err
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	_, err = a.conn.Write(b)
	return err
}

func (a *udsAsker) readLoop() {
	for {
		msg, err := readFrame(a.conn)
		if err != nil {
			fmt.Fprintln(os.Stderr, "silc loop: supervisor connection closed")
			os.Exit(0)
		}
		switch msg["type"] {
		case "SHUTDOWN":
			os.Exit(0)
		case "RESPONSE":
			id, _ := msg["request_id"].(string)
			a.mu.Lock()
			ch := a.waiters[id]
			delete(a.waiters, id)
			a.mu.Unlock()
			if ch != nil {
				ch <- msg
			}
		}
	}
}

func (a *udsAsker) Ask(req AskRequest) (string, error) {
	a.mu.Lock()
	a.next++
	id := fmt.Sprintf("ask-%d-%d", os.Getpid(), a.next)
	ch := make(chan map[string]any, 1)
	a.waiters[id] = ch
	a.mu.Unlock()
	if err := a.send(map[string]any{
		"type": "ASK", "request_id": id, "name": req.Loop,
		"prompt": req.Prompt, "context": req.Context, "schema": req.Schema,
	}); err != nil {
		return "", err
	}
	select {
	case msg := <-ch:
		if ok, _ := msg["ok"].(bool); !ok {
			errText, _ := msg["error"].(string)
			return "", fmt.Errorf("silclm: %s", errText)
		}
		reply, _ := msg["reply"].(string)
		return reply, nil
	case <-time.After(10 * time.Minute):
		a.mu.Lock()
		delete(a.waiters, id)
		a.mu.Unlock()
		return "", fmt.Errorf("silclm did not answer within 10 minutes")
	}
}

// udsEmbedder talks HTTP/JSON to the embed worker on SILC_EMBED_SOCKET.
type udsEmbedder struct {
	client *http.Client
}

func dialEmbedder(path string) *udsEmbedder {
	transport := &http.Transport{
		DialContext: func(ctx context.Context, _, _ string) (net.Conn, error) {
			var d net.Dialer
			return d.DialContext(ctx, "unix", path)
		},
	}
	return &udsEmbedder{client: &http.Client{Transport: transport, Timeout: 2 * time.Minute}}
}

func (e *udsEmbedder) post(path string, body any, out any) error {
	b, err := json.Marshal(body)
	if err != nil {
		return err
	}
	resp, err := e.client.Post("http://silc-embed"+path, "application/json", bytes.NewReader(b))
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(io.LimitReader(resp.Body, 64<<20))
	if err != nil {
		return err
	}
	if resp.StatusCode != http.StatusOK {
		var failure struct {
			Error string `json:"error"`
		}
		_ = json.Unmarshal(data, &failure)
		if failure.Error == "" {
			failure.Error = resp.Status
		}
		return errors.New(failure.Error)
	}
	return json.Unmarshal(data, out)
}

func (e *udsEmbedder) Embed(texts []string) ([][]float64, error) {
	var out struct {
		Vectors [][]float64 `json:"vectors"`
	}
	if err := e.post("/embed", map[string]any{"texts": texts}, &out); err != nil {
		return nil, err
	}
	return out.Vectors, nil
}

func (e *udsEmbedder) Nearest(table, needle string, limit int) ([]map[string]any, error) {
	var out struct {
		Rows []map[string]any `json:"rows"`
	}
	if err := e.post("/nearest", map[string]any{"table": table, "needle": needle, "limit": limit}, &out); err != nil {
		return nil, err
	}
	return out.Rows, nil
}

func (e *udsEmbedder) NearestVector(table string, vector []float64, limit int) ([]map[string]any, error) {
	var out struct {
		Rows []map[string]any `json:"rows"`
	}
	if err := e.post("/nearest", map[string]any{"table": table, "vector": vector, "limit": limit}, &out); err != nil {
		return nil, err
	}
	return out.Rows, nil
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

// kernelDBLock is an exclusive flock on `<db>.kernel.lock`. When held, a second
// kernel must refuse the same app.db. The kernel releases the lock on exit
// (including crash), so stale locks from dead processes never block a restart.
type kernelDBLock struct {
	f *os.File
}

func acquireKernelDBLock(dbPath string) (*kernelDBLock, error) {
	lockPath := dbPath + ".kernel.lock"
	if err := os.MkdirAll(filepath.Dir(dbPath), 0o755); err != nil {
		return nil, err
	}
	f, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		holder := strings.TrimSpace(readLockPID(f))
		_ = f.Close()
		if holder == "" {
			return nil, fmt.Errorf("app.db already has a live loop kernel (lock %s); stop that process before starting another", lockPath)
		}
		return nil, fmt.Errorf("app.db already has a live loop kernel (pid %s, lock %s); stop that process before starting another", holder, lockPath)
	}
	if err := f.Truncate(0); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	if _, err := f.Seek(0, 0); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	if _, err := fmt.Fprintf(f, "%d\n", os.Getpid()); err != nil {
		_ = syscall.Flock(int(f.Fd()), syscall.LOCK_UN)
		_ = f.Close()
		return nil, err
	}
	_ = f.Sync()
	return &kernelDBLock{f: f}, nil
}

func readLockPID(f *os.File) string {
	if _, err := f.Seek(0, 0); err != nil {
		return ""
	}
	buf := make([]byte, 64)
	n, err := f.Read(buf)
	if err != nil && err != io.EOF {
		return ""
	}
	return string(buf[:n])
}

func (l *kernelDBLock) Close() {
	if l == nil || l.f == nil {
		return
	}
	_ = syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
	_ = l.f.Close()
	l.f = nil
}

func main() {
	planPath := envOr("SILC_LOOP_PLAN", "loop/plan.json")
	dbPath := envOr("SILC_DB_PATH", "data/app.db")
	plan, err := loadPlan(planPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "silc loop:", err)
		os.Exit(1)
	}
	if err := os.MkdirAll(filepath.Dir(dbPath), 0o755); err != nil {
		fmt.Fprintln(os.Stderr, "silc loop:", err)
		os.Exit(1)
	}
	dbLock, err := acquireKernelDBLock(dbPath)
	if err != nil {
		fmt.Fprintln(os.Stderr, "silc loop:", err)
		os.Exit(1)
	}
	defer dbLock.Close()
	db, err := sql.Open("sqlite", "file:"+dbPath+"?_pragma=busy_timeout(5000)&_pragma=journal_mode(WAL)")
	if err != nil {
		fmt.Fprintln(os.Stderr, "silc loop:", err)
		os.Exit(1)
	}
	db.SetMaxOpenConns(1)
	k, err := NewKernel(db, plan, filepath.Join(filepath.Dir(planPath), "plans"))
	if err != nil {
		fmt.Fprintln(os.Stderr, "silc loop:", err)
		os.Exit(1)
	}
	if sock := os.Getenv("SILC_SOCKET"); sock != "" {
		asker, err := dialSupervisor(sock)
		if err != nil {
			k.logf("cannot reach supervisor (%v); loop::ask will fail", err)
		} else {
			k.asker = asker
		}
	}
	if sock := os.Getenv("SILC_EMBED_SOCKET"); sock != "" && plan.Embedding != nil {
		k.embedder = dialEmbedder(sock)
	}
	if os.Getenv("SILC_LOOP_ONCE") == "1" {
		// Command mode: run every manual loop once, print notices, exit.
		// Narrate each step on stderr; stdout carries only the notices.
		k.progress = k.logf
		by := envOr("SILC_LOOP_REQUESTED_BY", envOr("USER", "command line"))
		ok, err := k.RunOnce(by, os.Stdout)
		if err != nil {
			fmt.Fprintln(os.Stderr, "silc loop:", err)
			os.Exit(1)
		}
		if !ok {
			os.Exit(1)
		}
		return
	}
	tick := 1000
	if v, err := strconv.Atoi(os.Getenv("SILC_LOOP_TICK_MS")); err == nil && v > 0 {
		tick = v
	}
	k.logf("kernel ready: %d loop(s), plan %s", len(plan.Loops), plan.Hash[:12])
	for {
		k.Tick()
		time.Sleep(time.Duration(tick) * time.Millisecond)
	}
}
